SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @RequestId NVARCHAR(100) =
    N'{{ String($json.RequestId ?? "").trim().replaceAll("'", "''") }}';

DECLARE @SourceProfileListingId BIGINT =
    TRY_CONVERT(BIGINT, N'{{ String($json.SourceProfileListingId ?? "").trim().replaceAll("'", "''") }}');

DECLARE @TargetProfileListingId BIGINT =
    TRY_CONVERT(BIGINT, N'{{ String($json.TargetProfileListingId ?? "").trim().replaceAll("'", "''") }}');

DECLARE @SourceProfileListingKey NVARCHAR(255) =
    N'{{ String($json.SourceProfileListingKey ?? "").trim().replaceAll("'", "''") }}';

DECLARE @TargetProfileListingKey NVARCHAR(255) =
    N'{{ String($json.TargetProfileListingKey ?? "").trim().replaceAll("'", "''") }}';

DECLARE @SourceRatingRecordCount INT = 0;
DECLARE @DestinationRatingCountBefore INT = 0;
DECLARE @DestinationRatingCountAfter INT = 0;
DECLARE @SourceRatingCount BIGINT = 0;
DECLARE @DestinationRatingCount BIGINT = 0;
DECLARE @InsertedRows INT = 0;
DECLARE @InsertSucceeded BIT = 0;
DECLARE @InsertComment NVARCHAR(1000);

IF
    @SourceProfileListingId IS NULL
    OR @TargetProfileListingId IS NULL
    OR @SourceProfileListingId = @TargetProfileListingId
BEGIN
    SELECT
        @RequestId AS RequestId,
        @SourceProfileListingId AS SourceProfileListingId,
        @SourceProfileListingKey AS SourceProfileListingKey,
        @TargetProfileListingId AS TargetProfileListingId,
        @TargetProfileListingKey AS TargetProfileListingKey,
        0 AS SourceRatingRecordCount,
        0 AS SourceRatingCount,
        0 AS DestinationRatingCountBefore,
        0 AS DestinationRatingCount,
        0 AS DestinationRatingCountAfter,
        0 AS InsertedRows,
        CAST(0 AS BIT) AS InsertSucceeded,
        N'Blocked: invalid or identical ProfileListing IDs' AS InsertComment;
    RETURN;
END;

BEGIN TRY
    SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
    BEGIN TRANSACTION;

    SELECT
        @SourceRatingRecordCount = COUNT(*),
        @SourceRatingCount =
            COALESCE(MAX(CONVERT(BIGINT, RatingCount)), 0)
    FROM ProfileRatings WITH (UPDLOCK, HOLDLOCK)
    WHERE ProfileListingId = @SourceProfileListingId;

    SELECT
        @DestinationRatingCountBefore = COUNT(*),
        @DestinationRatingCount =
            COALESCE(MAX(CONVERT(BIGINT, RatingCount)), 0)
    FROM ProfileRatings WITH (UPDLOCK, HOLDLOCK)
    WHERE ProfileListingId = @TargetProfileListingId;

    IF @SourceRatingRecordCount = 0
    BEGIN
        SET @InsertComment = N'Blocked: source room has no rating record';
        ROLLBACK TRANSACTION;
    END
    ELSE IF @SourceRatingRecordCount > 1
    BEGIN
        SET @InsertComment = N'Blocked: source room has duplicate rating records';
        ROLLBACK TRANSACTION;
    END
    ELSE IF @DestinationRatingCount > @SourceRatingCount
    BEGIN
        SET @InsertComment =
            N'Blocked: destination RatingCount is greater than source';
        ROLLBACK TRANSACTION;
    END
    ELSE IF @DestinationRatingCountBefore > 0
    BEGIN
        SET @InsertComment =
            N'Blocked: destination already has a rating record';
        ROLLBACK TRANSACTION;
    END
    ELSE
    BEGIN
        INSERT INTO ProfileRatings
        (
            ProfileListingId,
            OverallRating,
            MedicalBackgroundRating,
            FriendlinessRating,
            WaitingTimeRating,
            UpdatedOn,
            NumberOfSurveys,
            WaitingTimeRatingCount,
            exampleRatingCount,
            RatingCount,
            DoctorRating,
            DoctorRatingCount,
            AdminRating,
            AdminRatingCount,
            FacilityRating,
            FacilityRatingCount,
            WaitingTimeTotalMinutesRating,
            WaitingTimeTotalMinutesRatingCount,
            CreatedOn
        )
        SELECT
            @TargetProfileListingId,
            sourceRating.OverallRating,
            sourceRating.MedicalBackgroundRating,
            sourceRating.FriendlinessRating,
            sourceRating.WaitingTimeRating,
            sourceRating.UpdatedOn,
            sourceRating.NumberOfSurveys,
            sourceRating.WaitingTimeRatingCount,
            sourceRating.exampleRatingCount,
            sourceRating.RatingCount,
            sourceRating.DoctorRating,
            sourceRating.DoctorRatingCount,
            sourceRating.AdminRating,
            sourceRating.AdminRatingCount,
            sourceRating.FacilityRating,
            sourceRating.FacilityRatingCount,
            sourceRating.WaitingTimeTotalMinutesRating,
            sourceRating.WaitingTimeTotalMinutesRatingCount,
            sourceRating.CreatedOn
        FROM ProfileRatings AS sourceRating
        WHERE sourceRating.ProfileListingId = @SourceProfileListingId;

        SET @InsertedRows = @@ROWCOUNT;

        SELECT
            @DestinationRatingCountAfter = COUNT(*)
        FROM ProfileRatings WITH (UPDLOCK, HOLDLOCK)
        WHERE ProfileListingId = @TargetProfileListingId;

        IF @InsertedRows = 1 AND @DestinationRatingCountAfter = 1
        BEGIN
            COMMIT TRANSACTION;
            SET @InsertSucceeded = 1;
            SET @InsertComment = N'Rating inserted successfully';
        END
        ELSE
        BEGIN
            ROLLBACK TRANSACTION;
            SET @InsertedRows = 0;
            SET @InsertSucceeded = 0;
            SET @InsertComment =
                N'Blocked: insert did not produce exactly one destination rating record';
        END;
    END;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    SET @InsertedRows = 0;
    SET @InsertSucceeded = 0;
    SET @InsertComment =
        CONCAT(N'Rating insert failed: ', ERROR_MESSAGE());
END CATCH;

SELECT
    @RequestId AS RequestId,
    @SourceProfileListingId AS SourceProfileListingId,
    @SourceProfileListingKey AS SourceProfileListingKey,
    @TargetProfileListingId AS TargetProfileListingId,
    @TargetProfileListingKey AS TargetProfileListingKey,
    @SourceRatingRecordCount AS SourceRatingRecordCount,
    @SourceRatingCount AS SourceRatingCount,
    @DestinationRatingCountBefore AS DestinationRatingCountBefore,
    @DestinationRatingCount AS DestinationRatingCount,
    @DestinationRatingCountAfter AS DestinationRatingCountAfter,
    @InsertedRows AS InsertedRows,
    @InsertSucceeded AS InsertSucceeded,
    @InsertComment AS InsertComment;

SET NOCOUNT ON;

DECLARE @RequestId NVARCHAR(100) =
    N'{{ String($json.RequestId ?? "").trim().replaceAll("'", "''") }}';

DECLARE @SourceProfileListingId BIGINT =
    TRY_CONVERT(BIGINT, N'{{ String($json.SourceProfileListingId ?? "").trim().replaceAll("'", "''") }}');

DECLARE @TargetProfileListingId BIGINT =
    TRY_CONVERT(BIGINT, N'{{ String($json.TargetProfileListingId ?? "").trim().replaceAll("'", "''") }}');

DECLARE @SourceProfileListingKey NVARCHAR(255) =
    N'{{ String($json.SourceProfileListingKey ?? "").trim().replaceAll("'", "''") }}';

DECLARE @TargetProfileListingKey NVARCHAR(255) =
    N'{{ String($json.TargetProfileListingKey ?? "").trim().replaceAll("'", "''") }}';

DECLARE @DestinationRatingCountAfter INT;
DECLARE @DestinationRatingCount BIGINT;

SELECT
    @DestinationRatingCountAfter = COUNT(*),
    @DestinationRatingCount =
        COALESCE(MAX(CONVERT(BIGINT, RatingCount)), 0)
FROM ProfileRatings
WHERE ProfileListingId = @TargetProfileListingId;

SELECT
    @RequestId AS RequestId,
    @SourceProfileListingId AS SourceProfileListingId,
    @SourceProfileListingKey AS SourceProfileListingKey,
    @TargetProfileListingId AS TargetProfileListingId,
    @TargetProfileListingKey AS TargetProfileListingKey,
    @DestinationRatingCountAfter AS DestinationRatingCountAfter,
    @DestinationRatingCount AS DestinationRatingCount,
    CAST(
        CASE
            WHEN @TargetProfileListingId IS NOT NULL
             AND @DestinationRatingCountAfter = 1
            THEN 1
            ELSE 0
        END
        AS BIT
    ) AS RatingVerificationPassed,
    CASE
        WHEN @TargetProfileListingId IS NULL
            THEN N'Verification failed: destination ProfileListingId is missing'
        WHEN @DestinationRatingCountAfter = 0
            THEN N'Verification failed: destination rating record was not found'
        WHEN @DestinationRatingCountAfter > 1
            THEN N'Critical: duplicate destination rating records detected'
        ELSE N'Destination rating verified successfully'
    END AS RatingVerificationComment;

