={{ (() => {
  const reason = String($json.BlockReason ?? $json.Comment ?? 'Processing was blocked');
  const ratingValues = [
    $json.SourceRatingCount,
    $json.DestinationRatingCountAfter,
    $json.DestinationRatingCountBefore,
    $json.DestinationRatingCount
  ];
  const hasRatingData = ratingValues.some(value =>
    value !== undefined &&
    value !== null &&
    String(value).trim() !== ''
  );
  return hasRatingData
    ? reason
      + ' | Source RatingCount: ' + String($json.SourceRatingCount ?? '')
      + ' | Destination rating rows: ' + String($json.DestinationRatingCountAfter ?? $json.DestinationRatingCountBefore ?? '')
      + ' | Destination RatingCount: ' + String($json.DestinationRatingCount ?? '')
    : reason;
})() }}

