return $input.all().flatMap((item, index) => {
  const row = item.json ?? {};
  const requestId = String(row.RequestId ?? '').trim();
  const status = String(row.AutomationStatus ?? '').trim().toLowerCase();
  const retry = String(row.RetryRequested ?? '').trim().toLowerCase();
  const nextStep = String(row.NextStep ?? '').trim();

  const explicitRetry = retry === 'yes' && status === 'blocked';
  const strandedPending = status === 'pending';
  const shouldResume = Boolean(requestId && nextStep && (explicitRetry || strandedPending));

  if (!shouldResume) return [];

  return [{
    json: {
      ...row,
      RecoveryReason: explicitRetry ? 'Explicit retry' : 'Reclaimed pending request',
    },
    pairedItem: { item: index },
  }];
});

