const salesRows = $input.all().map(item => item.json ?? {});
const queueRows = $('Get Automation Queue Rows')
  .all()
  .map(item => item.json ?? {});

const text = value => String(value ?? '').trim();
const lower = value => text(value).toLowerCase();

const queueIds = new Set(
  queueRows
    .map(row => text(row.RequestId))
    .filter(Boolean)
);

// Resume requests that already exist in the private queue.
const retryItems = queueRows
  .filter(row => {
    const requestId = text(row.RequestId);
    const status = lower(row.AutomationStatus);
    const retryRequested = lower(row.RetryRequested);
    const nextStep = text(row.NextStep);

    const startedAt = Date.parse(text(row.StartedAt));
    const staleProcessing =
      status === 'processing' &&
      Number.isFinite(startedAt) &&
      Date.now() - startedAt > 2 * 60 * 60 * 1000;

    const explicitRetry =
      status === 'blocked' && retryRequested === 'yes';

    const pendingRequest = status === 'pending';

    return Boolean(
      requestId &&
      nextStep &&
      (explicitRetry || pendingRequest || staleProcessing)
    );
  })
  .map(row => ({
    json: {
      ...row,
      WorkMode: 'Retry',
      RecoveryReason:
        lower(row.AutomationStatus) === 'pending'
          ? 'Reclaimed pending request'
          : lower(row.AutomationStatus) === 'processing'
            ? 'Reclaimed stale processing request'
            : 'Explicit retry',
    },
  }));

// Add approved requests that are not already in the private queue.
const newItems = salesRows
  .filter(row => {
    const requestId = text(row.RequestId);
    const automationComment = lower(row['Automation Comment']);

    const eligibleComment =
      !automationComment ||
      automationComment === 'queued for processing';

    return (
      lower(row.Approval) === 'approved' &&
      Boolean(requestId) &&
      Boolean(text(row.OldRoomKey)) &&
      Boolean(text(row.NewRoomKey)) &&
      !text(row['Dev Action']) &&
      eligibleComment &&
      !queueIds.has(requestId)
    );
  })
  .map(row => ({
    json: {
      ...row,
      WorkMode: 'New',
      AlreadyQueued: false,
    },
  }));

return [...retryItems, ...newItems];
